RRB.load({"id": "ntpc-full-3", "exam": "ntpc", "label": "NTPC UG full mock 3 (100 Q)", "questions": [{"s": "General Awareness", "t": "History", "q": "Who was the first Governor-General of independent India?", "o": ["C. Rajagopalachari", "Lord Wavell", "Lord Linlithgow", "Lord Mountbatten"], "a": 3, "e": "Lord Mountbatten continued as the first Governor-General of independent India (1947–48); C. Rajagopalachari was the first and only Indian Governor-General.", "qh": "स्वतंत्र भारत के पहले गवर्नर-जनरल कौन थे?", "oh": ["सी. राजगोपालाचारी", "लॉर्ड वेवेल", "लॉर्ड लिनलिथगो", "लॉर्ड माउंटबेटन"], "eh": "लॉर्ड माउंटबेटन स्वतंत्र भारत के पहले गवर्नर-जनरल (1947–48) रहे; सी. राजगोपालाचारी पहले और आखिरी भारतीय गवर्नर-जनरल थे।", "level": "easy"}, {"s": "General Awareness", "t": "Current Affairs", "q": "The houselisting phase of which national exercise began on 1 April 2026?", "o": ["National Family Health Survey-6", "Seventh Economic Census", "Census 2027", "Agriculture Census"], "a": 2, "e": "Phase I (House Listing and Housing Census) of Census 2027 — India's first digital census — began on 1 April 2026.", "qh": "1 अप्रैल 2026 से किस राष्ट्रीय काम का मकान-सूचीकरण (हाउसलिस्टिंग) चरण शुरू हुआ?", "oh": ["राष्ट्रीय परिवार स्वास्थ्य सर्वेक्षण-6", "सातवीं आर्थिक गणना", "जनगणना 2027", "कृषि गणना"], "eh": "जनगणना 2027 — भारत की पहली डिजिटल जनगणना — का पहला चरण (मकान-सूचीकरण) 1 अप्रैल 2026 से शुरू हुआ।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "Under which Article can the President declare a Financial Emergency?", "o": ["Article 352", "Article 356", "Article 360", "Article 365"], "a": 2, "e": "Article 360 deals with Financial Emergency; 352 is National Emergency and 356 is President's Rule.", "qh": "राष्ट्रपति किस अनुच्छेद के तहत वित्तीय आपातकाल घोषित कर सकते हैं?", "oh": ["अनुच्छेद 352", "अनुच्छेद 356", "अनुच्छेद 360", "अनुच्छेद 365"], "eh": "अनुच्छेद 360 वित्तीय आपातकाल से जुड़ा है; 352 राष्ट्रीय आपातकाल और 356 राष्ट्रपति शासन है।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "In most Windows programs, which shortcut undoes the last action?", "o": ["Ctrl + Z", "Ctrl + Y", "Ctrl + X", "Ctrl + U"], "a": 0, "e": "Ctrl + Z is Undo; Ctrl + Y is Redo and Ctrl + X is Cut.", "qh": "ज़्यादातर Windows प्रोग्रामों में पिछला काम वापस (Undo) करने का शॉर्टकट कौन-सा है?", "oh": ["Ctrl + Z", "Ctrl + Y", "Ctrl + X", "Ctrl + U"], "eh": "Ctrl + Z से Undo, Ctrl + Y से Redo और Ctrl + X से Cut होता है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Vijayanagara Empire was founded in 1336 by Harihara and his brother:", "o": ["Bukka", "Krishnadeva Raya", "Devaraya", "Rama Raya"], "a": 0, "e": "Harihara I and Bukka Raya I of the Sangama dynasty founded Vijayanagara in 1336.", "qh": "1336 में विजयनगर साम्राज्य की स्थापना हरिहर और उनके किस भाई ने की?", "oh": ["बुक्का", "कृष्णदेव राय", "देवराय", "राम राय"], "eh": "संगम वंश के हरिहर प्रथम और बुक्का राय प्रथम ने 1336 में विजयनगर की स्थापना की।", "level": "tough"}, {"s": "General Awareness", "t": "Awards", "q": "Which veteran actor received the Dadasaheb Phalke Award at the 72nd National Film Awards ceremony held in September 2026?", "o": ["Mohanlal", "Mithun Chakraborty", "Waheeda Rehman", "Anant Nag"], "a": 3, "e": "Anant Nag received the Dadasaheb Phalke Award (for 2024) at the ceremony on 22 September 2026.", "qh": "सितंबर 2026 में हुए 72वें राष्ट्रीय फ़िल्म पुरस्कार समारोह में किस वरिष्ठ अभिनेता को दादासाहेब फाल्के पुरस्कार मिला?", "oh": ["मोहनलाल", "मिथुन चक्रवर्ती", "वहीदा रहमान", "अनंत नाग"], "eh": "22 सितंबर 2026 के समारोह में अनंत नाग को (2024 का) दादासाहेब फाल्के पुरस्कार मिला।", "level": "medium"}, {"s": "General Awareness", "t": "Railways", "q": "India's first passenger train ran on 16 April 1853 between Bori Bunder (Bombay) and:", "o": ["Kalyan", "Thane", "Pune", "Lonavala"], "a": 1, "e": "The first passenger train ran about 34 km from Bori Bunder to Thane.", "qh": "भारत की पहली यात्री ट्रेन 16 अप्रैल 1853 को बोरी बंदर (बंबई) से कहाँ तक चली?", "oh": ["कल्याण", "ठाणे", "पुणे", "लोनावला"], "eh": "पहली यात्री ट्रेन बोरी बंदर से ठाणे तक लगभग 34 km चली।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Which part of the human eye controls the size of the pupil?", "o": ["Retina", "Cornea", "Iris", "Lens"], "a": 2, "e": "The iris (coloured part) widens or narrows the pupil to control light entering the eye.", "qh": "मानव आँख का कौन-सा भाग पुतली (प्यूपिल) का आकार नियंत्रित करता है?", "oh": ["रेटिना", "कॉर्निया", "परितारिका (आइरिस)", "लेंस"], "eh": "आइरिस (रंगीन भाग) पुतली को छोटा-बड़ा करके आँख में जाने वाली रोशनी नियंत्रित करता है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which channel separates the Andaman Islands from the Nicobar Islands?", "o": ["Ten Degree Channel", "Nine Degree Channel", "Eight Degree Channel", "Palk Strait"], "a": 0, "e": "The Ten Degree Channel lies between Little Andaman and Car Nicobar.", "qh": "कौन-सा चैनल अंडमान द्वीपों को निकोबार द्वीपों से अलग करता है?", "oh": ["टेन डिग्री चैनल", "नाइन डिग्री चैनल", "एट डिग्री चैनल", "पाक जलडमरूमध्य"], "eh": "टेन डिग्री चैनल लिटिल अंडमान और कार निकोबार के बीच है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The Mahalanobis model is associated with which Five-Year Plan?", "o": ["First Five-Year Plan", "Second Five-Year Plan", "Third Five-Year Plan", "Fifth Five-Year Plan"], "a": 1, "e": "The Second Plan (1956–61), focused on heavy industry, was based on P. C. Mahalanobis's model.", "qh": "महालनोबिस मॉडल किस पंचवर्षीय योजना से जुड़ा है?", "oh": ["पहली पंचवर्षीय योजना", "दूसरी पंचवर्षीय योजना", "तीसरी पंचवर्षीय योजना", "पाँचवीं पंचवर्षीय योजना"], "eh": "भारी उद्योग पर ज़ोर देने वाली दूसरी योजना (1956–61) पी. सी. महालनोबिस के मॉडल पर आधारित थी।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "Panchayati Raj institutions got constitutional status through which amendment?", "o": ["74th Amendment", "61st Amendment", "52nd Amendment", "73rd Amendment"], "a": 3, "e": "The 73rd Amendment (1992) gave constitutional status to Panchayats; the 74th did so for urban local bodies.", "qh": "पंचायती राज संस्थाओं को संवैधानिक दर्जा किस संशोधन से मिला?", "oh": ["74वाँ संशोधन", "61वाँ संशोधन", "52वाँ संशोधन", "73वाँ संशोधन"], "eh": "73वें संशोधन (1992) ने पंचायतों को संवैधानिक दर्जा दिया; 74वें ने शहरी निकायों को।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Madhubani painting is a folk art of which state?", "o": ["West Bengal", "Odisha", "Bihar", "Jharkhand"], "a": 2, "e": "Madhubani (Mithila) painting comes from the Mithila region of Bihar.", "qh": "मधुबनी चित्रकला किस राज्य की लोककला है?", "oh": ["पश्चिम बंगाल", "ओडिशा", "बिहार", "झारखंड"], "eh": "मधुबनी (मिथिला) चित्रकला बिहार के मिथिला क्षेत्र की है।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who became the Chief Minister of Kerala in May 2026?", "o": ["Pinarayi Vijayan", "Ramesh Chennithala", "V. D. Satheesan", "Shashi Tharoor"], "a": 2, "e": "Congress leader V. D. Satheesan was sworn in on 18 May 2026 after the UDF's win.", "qh": "मई 2026 में केरल के मुख्यमंत्री कौन बने?", "oh": ["पिनराई विजयन", "रमेश चेन्निथला", "वी. डी. सतीशन", "शशि थरूर"], "eh": "UDF की जीत के बाद कांग्रेस नेता वी. डी. सतीशन ने 18 मई 2026 को शपथ ली।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Who founded the Arya Samaj in 1875?", "o": ["Raja Ram Mohan Roy", "Swami Dayanand Saraswati", "Swami Vivekananda", "Keshab Chandra Sen"], "a": 1, "e": "Swami Dayanand Saraswati founded the Arya Samaj in Bombay in 1875.", "qh": "1875 में आर्य समाज की स्थापना किसने की?", "oh": ["राजा राममोहन राय", "स्वामी दयानंद सरस्वती", "स्वामी विवेकानंद", "केशवचंद्र सेन"], "eh": "स्वामी दयानंद सरस्वती ने 1875 में बंबई में आर्य समाज की स्थापना की।", "level": "tough"}, {"s": "General Awareness", "t": "Economy", "q": "Indian currency notes (other than the ₹1 note) are signed by:", "o": ["the Governor of the RBI", "the Finance Minister", "the Finance Secretary", "the Prime Minister"], "a": 0, "e": "The RBI Governor signs all notes except the ₹1 note, which the Finance Secretary signs.", "qh": "भारतीय नोटों (₹1 के नोट को छोड़कर) पर किसके हस्ताक्षर होते हैं?", "oh": ["RBI के गवर्नर", "वित्त मंत्री", "वित्त सचिव", "प्रधानमंत्री"], "eh": "₹1 के नोट को छोड़कर सभी नोटों पर RBI गवर्नर के हस्ताक्षर होते हैं; ₹1 पर वित्त सचिव के।", "level": "easy"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Which festival marks the Assamese New Year in mid-April?", "o": ["Magh (Bhogali) Bihu", "Bohag (Rongali) Bihu", "Kati (Kongali) Bihu", "Ali Ai Ligang"], "a": 1, "e": "Bohag or Rongali Bihu in April marks the Assamese New Year and the spring harvest season.", "qh": "अप्रैल के बीच में असमिया नया साल किस त्योहार से शुरू होता है?", "oh": ["माघ (भोगाली) बिहू", "बोहाग (रोंगाली) बिहू", "काती (कोंगाली) बिहू", "अली आई लिगांग"], "eh": "अप्रैल का बोहाग या रोंगाली बिहू असमिया नया साल और बसंत की फ़सल का समय है।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "How many members can the President nominate to the Rajya Sabha?", "o": ["10", "14", "12", "2"], "a": 2, "e": "Article 80 allows the President to nominate 12 members with special knowledge of literature, science, art and social service.", "qh": "राष्ट्रपति राज्यसभा में कितने सदस्य मनोनीत कर सकते हैं?", "oh": ["10", "14", "12", "2"], "eh": "अनुच्छेद 80 के तहत राष्ट्रपति साहित्य, विज्ञान, कला और समाज सेवा के जानकार 12 सदस्य मनोनीत करते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Third Battle of Panipat (1761) was fought between the Marathas and:", "o": ["Ahmad Shah Abdali", "Nadir Shah", "Babur", "Ibrahim Lodi"], "a": 0, "e": "In 1761 Ahmad Shah Abdali (Durrani) defeated the Marathas at Panipat.", "qh": "पानीपत की तीसरी लड़ाई (1761) मराठों और किसके बीच हुई?", "oh": ["अहमद शाह अब्दाली", "नादिर शाह", "बाबर", "इब्राहिम लोदी"], "eh": "1761 में अहमद शाह अब्दाली (दुर्रानी) ने पानीपत में मराठों को हराया।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "In which year was the 'Make in India' initiative launched?", "o": ["2016", "2012", "2019", "2014"], "a": 3, "e": "Make in India was launched on 25 September 2014 to boost manufacturing.", "qh": "'मेक इन इंडिया' पहल किस साल शुरू की गई?", "oh": ["2016", "2012", "2019", "2014"], "eh": "मेक इन इंडिया 25 सितंबर 2014 को निर्माण (मैन्युफ़ैक्चरिंग) बढ़ाने के लिए शुरू हुई।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "NITI Aayog replaced which body in January 2015?", "o": ["Finance Commission", "National Development Council", "Inter-State Council", "Planning Commission"], "a": 3, "e": "NITI Aayog was set up on 1 January 2015 in place of the Planning Commission.", "qh": "जनवरी 2015 में नीति आयोग ने किस संस्था की जगह ली?", "oh": ["वित्त आयोग", "राष्ट्रीय विकास परिषद", "अंतर-राज्य परिषद", "योजना आयोग"], "eh": "नीति आयोग 1 जनवरी 2015 को योजना आयोग की जगह बना।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "The Hogenakkal Falls are on which river?", "o": ["Krishna", "Kaveri", "Tungabhadra", "Godavari"], "a": 1, "e": "Hogenakkal Falls are on the Kaveri, on the Tamil Nadu–Karnataka border.", "qh": "होगेनक्कल जलप्रपात किस नदी पर है?", "oh": ["कृष्णा", "कावेरी", "तुंगभद्रा", "गोदावरी"], "eh": "होगेनक्कल जलप्रपात कावेरी नदी पर, तमिलनाडु–कर्नाटक सीमा के पास है।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "Which country won the FIFA World Cup 2026?", "o": ["Argentina", "Spain", "France", "Brazil"], "a": 1, "e": "Spain beat Argentina 1–0 after extra time in the final on 19 July 2026 to win their second World Cup.", "qh": "फ़ीफ़ा विश्व कप 2026 किस देश ने जीता?", "oh": ["अर्जेंटीना", "स्पेन", "फ़्रांस", "ब्राज़ील"], "eh": "19 जुलाई 2026 को फ़ाइनल में स्पेन ने अर्जेंटीना को अतिरिक्त समय में 1–0 से हराकर दूसरी बार विश्व कप जीता।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Who is the ex-officio Chairman of the Rajya Sabha?", "o": ["The Speaker of the Lok Sabha", "The President of India", "The Vice-President of India", "The Prime Minister"], "a": 2, "e": "Under Article 64, the Vice-President is the ex-officio Chairman of the Rajya Sabha.", "qh": "राज्यसभा का पदेन सभापति कौन होता है?", "oh": ["लोकसभा अध्यक्ष", "भारत के राष्ट्रपति", "भारत के उपराष्ट्रपति", "प्रधानमंत्री"], "eh": "अनुच्छेद 64 के अनुसार उपराष्ट्रपति राज्यसभा के पदेन सभापति होते हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "Which Part of the Constitution of India deals with Fundamental Rights?", "o": ["Part IV", "Part II", "Part V", "Part III"], "a": 3, "e": "Fundamental Rights are in Part III (Articles 12–35).", "qh": "भारत के संविधान का कौन-सा भाग मौलिक अधिकारों से जुड़ा है?", "oh": ["भाग IV", "भाग II", "भाग V", "भाग III"], "eh": "मौलिक अधिकार भाग III (अनुच्छेद 12–35) में हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which is the highest peak of the Western Ghats?", "o": ["Anamudi", "Doddabetta", "Mahendragiri", "Kalsubai"], "a": 0, "e": "Anamudi (about 2,695 m) in Kerala is the highest peak of the Western Ghats and of South India.", "qh": "पश्चिमी घाट की सबसे ऊँची चोटी कौन-सी है?", "oh": ["अनामुडी", "डोड्डाबेट्टा", "महेंद्रगिरि", "कलसुबाई"], "eh": "केरल की अनामुडी (लगभग 2,695 m) पश्चिमी घाट और दक्षिण भारत की सबसे ऊँची चोटी है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Sound cannot travel through:", "o": ["Vacuum", "Water", "Steel", "Air"], "a": 0, "e": "Sound needs a medium; it cannot travel through a vacuum.", "qh": "ध्वनि किसमें से होकर नहीं जा सकती?", "oh": ["निर्वात (वैक्यूम)", "पानी", "स्टील", "हवा"], "eh": "ध्वनि को चलने के लिए माध्यम चाहिए; निर्वात में यह नहीं चलती।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who took oath as Chief Minister of Assam for a second consecutive term on 12 May 2026?", "o": ["Sarbananda Sonowal", "Gaurav Gogoi", "Atul Bora", "Himanta Biswa Sarma"], "a": 3, "e": "Himanta Biswa Sarma returned as Assam CM after the NDA won 92 of 126 seats.", "qh": "12 मई 2026 को लगातार दूसरी बार असम के मुख्यमंत्री के रूप में किसने शपथ ली?", "oh": ["सर्बानंद सोनोवाल", "गौरव गोगोई", "अतुल बोरा", "हिमंत बिस्वा सरमा"], "eh": "NDA के 126 में से 92 सीटें जीतने के बाद हिमंत बिस्वा सरमा फिर मुख्यमंत्री बने।", "level": "tough"}, {"s": "General Awareness", "t": "Static GK", "q": "Which animal was declared the National Heritage Animal of India in 2010?", "o": ["Elephant", "Tiger", "Lion", "One-horned rhinoceros"], "a": 0, "e": "The Indian elephant was declared the National Heritage Animal in 2010; the tiger is the national animal.", "qh": "2010 में किस जानवर को भारत का राष्ट्रीय धरोहर पशु घोषित किया गया?", "oh": ["हाथी", "बाघ", "शेर", "एक सींग वाला गैंडा"], "eh": "2010 में भारतीय हाथी को राष्ट्रीय धरोहर पशु घोषित किया गया; बाघ राष्ट्रीय पशु है।", "level": "easy"}, {"s": "General Awareness", "t": "Science & Tech", "q": "The Nobel Prize in Physics 2026 was awarded to Francis Halzen for leading which neutrino observatory at the South Pole?", "o": ["Super-Kamiokande", "IceCube", "LIGO", "Event Horizon Telescope"], "a": 1, "e": "Francis Halzen won the 2026 Physics Nobel for IceCube's discovery of high-energy cosmic neutrinos.", "qh": "2026 का भौतिकी नोबेल पुरस्कार फ़्रांसिस हाल्ज़ेन को दक्षिणी ध्रुव पर किस न्यूट्रिनो वेधशाला के लिए मिला?", "oh": ["सुपर-कामिओकांडे", "आइसक्यूब (IceCube)", "LIGO", "इवेंट होराइज़न टेलीस्कोप"], "eh": "फ़्रांसिस हाल्ज़ेन को आइसक्यूब द्वारा उच्च-ऊर्जा कॉस्मिक न्यूट्रिनो की खोज के लिए 2026 का भौतिकी नोबेल मिला।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Which gas do green plants take in from the air for photosynthesis?", "o": ["Carbon dioxide", "Oxygen", "Nitrogen", "Hydrogen"], "a": 0, "e": "Plants use carbon dioxide and water to make glucose, giving out oxygen.", "qh": "हरे पौधे प्रकाश-संश्लेषण के लिए हवा से कौन-सी गैस लेते हैं?", "oh": ["कार्बन डाइऑक्साइड", "ऑक्सीजन", "नाइट्रोजन", "हाइड्रोजन"], "eh": "पौधे कार्बन डाइऑक्साइड और पानी से ग्लूकोज़ बनाते हैं और ऑक्सीजन छोड़ते हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Which city hosted the Commonwealth Games in July–August 2026?", "o": ["Glasgow", "Birmingham", "Gold Coast", "Victoria"], "a": 0, "e": "The 2026 Commonwealth Games were held in Glasgow, Scotland. (Birmingham hosted 2022.)", "qh": "जुलाई–अगस्त 2026 में राष्ट्रमंडल खेल किस शहर में हुए?", "oh": ["ग्लासगो", "बर्मिंघम", "गोल्ड कोस्ट", "विक्टोरिया"], "eh": "2026 के राष्ट्रमंडल खेल ग्लासगो (स्कॉटलैंड) में हुए। (2022 में बर्मिंघम मेज़बान था।)", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Loktak Lake, famous for its floating 'phumdis', is in which state?", "o": ["Meghalaya", "Assam", "Manipur", "Tripura"], "a": 2, "e": "Loktak Lake in Manipur has floating vegetation masses called phumdis.", "qh": "तैरते 'फुमदी' के लिए मशहूर लोकटक झील किस राज्य में है?", "oh": ["मेघालय", "असम", "मणिपुर", "त्रिपुरा"], "eh": "मणिपुर की लोकटक झील में तैरती वनस्पति 'फुमदी' होती है।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "ISRO's NVS series of satellites is mainly used for:", "o": ["Navigation (NavIC)", "Weather forecasting", "Direct-to-home TV", "Studying the Sun"], "a": 0, "e": "NVS satellites are the second-generation satellites of India's NavIC navigation system.", "qh": "इसरो के NVS शृंखला के उपग्रह मुख्य रूप से किस काम के लिए हैं?", "oh": ["नेविगेशन (NavIC)", "मौसम का अनुमान", "डायरेक्ट-टू-होम टीवी", "सूरज का अध्ययन"], "eh": "NVS उपग्रह भारत की NavIC नेविगेशन प्रणाली की दूसरी पीढ़ी के उपग्रह हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which Indian state shares its border with the largest number of other states?", "o": ["Assam", "Uttar Pradesh", "Madhya Pradesh", "Maharashtra"], "a": 1, "e": "Uttar Pradesh borders eight states (Uttarakhand, Himachal, Haryana, Rajasthan, MP, Chhattisgarh, Jharkhand, Bihar) plus Delhi.", "qh": "भारत का कौन-सा राज्य सबसे ज़्यादा राज्यों के साथ सीमा साझा करता है?", "oh": ["असम", "उत्तर प्रदेश", "मध्य प्रदेश", "महाराष्ट्र"], "eh": "उत्तर प्रदेश की सीमा आठ राज्यों (उत्तराखंड, हिमाचल, हरियाणा, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, बिहार) और दिल्ली से लगती है।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "In which year did the Jallianwala Bagh massacre take place?", "o": ["1919", "1920", "1917", "1922"], "a": 0, "e": "The massacre at Amritsar happened on 13 April 1919 (Baisakhi).", "qh": "जलियाँवाला बाग हत्याकांड किस साल हुआ था?", "oh": ["1919", "1920", "1917", "1922"], "eh": "अमृतसर में यह हत्याकांड 13 अप्रैल 1919 (बैसाखी) को हुआ।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "What is the full form of URL?", "o": ["Uniform Resource Locator", "Universal Resource Link", "Uniform Routing Locator", "Universal Record Locator"], "a": 0, "e": "URL stands for Uniform Resource Locator — a web address.", "qh": "URL का पूरा नाम क्या है?", "oh": ["Uniform Resource Locator", "Universal Resource Link", "Uniform Routing Locator", "Universal Record Locator"], "eh": "URL यानी Uniform Resource Locator — वेब पता।", "level": "easy"}, {"s": "General Awareness", "t": "Sports", "q": "Which two athletes were India's flag-bearers at the opening ceremony of the Asian Games 2026 in Aichi-Nagoya (19 September 2026)?", "o": ["Neeraj Chopra and P. V. Sindhu", "Manu Bhaker and Tajinderpal Singh Toor", "Lovlina Borgohain and Harmanpreet Singh", "Manu Bhaker and Pawan Sehrawat"], "a": 3, "e": "Shooter Manu Bhaker and kabaddi star Pawan Sehrawat led India; Sehrawat replaced shot-putter Tajinderpal Singh Toor at the last minute.", "qh": "आइची-नागोया एशियाई खेल 2026 के उद्घाटन समारोह (19 सितंबर 2026) में भारत के ध्वजवाहक कौन-से दो खिलाड़ी थे?", "oh": ["नीरज चोपड़ा और पी. वी. सिंधु", "मनु भाकर और तजिंदरपाल सिंह तूर", "लवलीना बोरगोहेन और हरमनप्रीत सिंह", "मनु भाकर और पवन सहरावत"], "eh": "निशानेबाज़ मनु भाकर और कबड्डी स्टार पवन सहरावत ने भारत की अगुवाई की; आखिरी समय में सहरावत ने गोला फेंक खिलाड़ी तजिंदरपाल सिंह तूर की जगह ली।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The Right to Education (Article 21A) was added to the Constitution by which amendment?", "o": ["86th Amendment", "42nd Amendment", "44th Amendment", "73rd Amendment"], "a": 0, "e": "The 86th Amendment Act, 2002 inserted Article 21A (free and compulsory education for ages 6–14).", "qh": "शिक्षा का अधिकार (अनुच्छेद 21A) किस संशोधन से संविधान में जोड़ा गया?", "oh": ["86वाँ संशोधन", "42वाँ संशोधन", "44वाँ संशोधन", "73वाँ संशोधन"], "eh": "86वें संशोधन अधिनियम, 2002 ने अनुच्छेद 21A जोड़ा (6–14 साल के बच्चों को मुफ़्त और अनिवार्य शिक्षा)।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was sworn in as the Chief Minister of Tamil Nadu on 10 May 2026?", "o": ["C. Joseph Vijay", "M. K. Stalin", "Edappadi K. Palaniswami", "K. Annamalai"], "a": 0, "e": "Actor-politician Vijay, whose party TVK won 108 seats, took oath as Tamil Nadu CM on 10 May 2026.", "qh": "10 मई 2026 को तमिलनाडु के मुख्यमंत्री के रूप में किसने शपथ ली?", "oh": ["सी. जोसेफ़ विजय", "एम. के. स्टालिन", "एडप्पाडी के. पलानीस्वामी", "के. अन्नामलाई"], "eh": "अभिनेता से नेता बने विजय, जिनकी पार्टी TVK ने 108 सीटें जीतीं, ने 10 मई 2026 को शपथ ली।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which Gupta ruler is called the 'Napoleon of India' by historians?", "o": ["Chandragupta II", "Samudragupta", "Skandagupta", "Kumaragupta I"], "a": 1, "e": "V. A. Smith called Samudragupta the 'Napoleon of India' for his many conquests.", "qh": "इतिहासकार किस गुप्त शासक को 'भारत का नेपोलियन' कहते हैं?", "oh": ["चंद्रगुप्त द्वितीय", "समुद्रगुप्त", "स्कंदगुप्त", "कुमारगुप्त प्रथम"], "eh": "वी. ए. स्मिथ ने कई जीतों के कारण समुद्रगुप्त को 'भारत का नेपोलियन' कहा।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "A bag contains ₹1, 50-paise and 25-paise coins in the ratio 3 : 4 : 5. If the total value is ₹75, how many 50-paise coins are there?", "o": ["48", "60", "36", "96"], "a": 0, "e": "Value of one set (3, 4, 5 coins) = 3 × 1 + 4 × ½ + 5 × ¼ = ₹6.25. Sets = 75 ÷ 6.25 = 12; 50-paise coins = 4 × 12 = 48.", "qh": "एक थैली में ₹1, 50 पैसे और 25 पैसे के सिक्के 3 : 4 : 5 के अनुपात में हैं। अगर कुल रकम ₹75 है, तो 50 पैसे के कितने सिक्के हैं?", "oh": ["48", "60", "36", "96"], "eh": "एक सेट (3, 4, 5 सिक्के) की कीमत = 3 × 1 + 4 × ½ + 5 × ¼ = ₹6.25। सेट = 75 ÷ 6.25 = 12; 50 पैसे के सिक्के = 4 × 12 = 48।", "level": "tough"}, {"s": "Mathematics", "t": "Algebra", "q": "If x + 1/x = 6, what is the value of x⁴ + 1/x⁴?", "o": ["1294", "1296", "1154", "1156"], "a": 2, "e": "x² + 1/x² = 36 − 2 = 34; x⁴ + 1/x⁴ = 34² − 2 = 1154.", "qh": "अगर x + 1/x = 6 है, तो x⁴ + 1/x⁴ का मान क्या है?", "oh": ["1294", "1296", "1154", "1156"], "eh": "x² + 1/x² = 36 − 2 = 34; x⁴ + 1/x⁴ = 34² − 2 = 1154।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "A batsman has a certain average after 15 innings. In the 16th innings he scores 74 runs, which raises his average by 2. What is his new average?", "o": ["42", "44", "45", "46"], "a": 1, "e": "Let old average = x. 15x + 74 = 16(x + 2) → x = 74 − 32 = 42. New average = 44.", "qh": "15 पारियों के बाद एक बल्लेबाज़ का कोई औसत है। 16वीं पारी में वह 74 रन बनाता है, जिससे उसका औसत 2 बढ़ जाता है। उसका नया औसत क्या है?", "oh": ["42", "44", "45", "46"], "eh": "पुराना औसत = x। 15x + 74 = 16(x + 2) → x = 74 − 32 = 42। नया औसत = 44।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "Two pipes can fill a tank in 12 hours and 15 hours respectively. If both are opened together, in how many hours will the tank be full?", "o": ["17/3 hours", "20/3 hours", "40/3 hours", "26/3 hours"], "a": 1, "e": "Per hour = 1/12 + 1/15 = 0.15 → 20/3 hours.", "qh": "दो पाइप एक टंकी को क्रमशः 12 घंटे और 15 घंटे में भर सकते हैं। दोनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["17/3 घंटे", "20/3 घंटे", "40/3 घंटे", "26/3 घंटे"], "eh": "हर घंटे = 1/12 + 1/15 = 0.15 → 20/3 घंटे।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the smallest number which, when divided by 10, 12 and 15, leaves a remainder of 1 in each case?", "o": ["121", "62", "59", "61"], "a": 3, "e": "LCM(10, 12, 15) = 60; number = 60 + 1 = 61.", "qh": "वह सबसे छोटी संख्या कौन-सी है जिसे 10, 12 और 15 से भाग देने पर हर बार 1 शेष बचे?", "oh": ["121", "62", "59", "61"], "eh": "LCM(10, 12, 15) = 60; संख्या = 60 + 1 = 61।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "Vikas's salary is 100% more than Rohit's salary. By what percentage is Rohit's salary less than Vikas's?", "o": ["75%", "100%", "55%", "50%"], "a": 3, "e": "Take Rohit = 100, Vikas = 200. Less by 100/200 × 100 = 50%.", "qh": "विकास की तनख्वाह रोहित की तनख्वाह से 100% ज़्यादा है। रोहित की तनख्वाह विकास की तनख्वाह से कितने प्रतिशत कम है?", "oh": ["75%", "100%", "55%", "50%"], "eh": "रोहित = 100 मानें, विकास = 200। कम = 100/200 × 100 = 50%।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "What is each exterior angle of a regular polygon with 5 sides?", "o": ["108°", "72°", "82°", "36°"], "a": 1, "e": "Exterior angle = 360°/5 = 72°.", "qh": "5 भुजाओं वाले सम बहुभुज का हर बाहरी कोण कितना होता है?", "oh": ["108°", "72°", "82°", "36°"], "eh": "बाहरी कोण = 360°/5 = 72°।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "What is the simple interest on ₹8,000 at 10% per annum for 2 years?", "o": ["₹9,600", "₹2,400", "₹800", "₹1,600"], "a": 3, "e": "SI = P × R × T/100 = 8000 × 10 × 2/100 = ₹1,600.", "qh": "₹8,000 पर 10% वार्षिक दर से 2 साल का साधारण ब्याज कितना होगा?", "oh": ["₹9,600", "₹2,400", "₹800", "₹1,600"], "eh": "साधारण ब्याज = P × R × T/100 = 8000 × 10 × 2/100 = ₹1,600।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "What is the mode of: 38, 17, 18, 17, 20, 12, 42, 49, 9, 17, 23?", "o": ["9", "17", "18", "38"], "a": 1, "e": "17 occurs most often (3 times), so mode = 17.", "qh": "38, 17, 18, 17, 20, 12, 42, 49, 9, 17, 23 का बहुलक क्या है?", "oh": ["9", "17", "18", "38"], "eh": "17 सबसे ज़्यादा बार (3 बार) आता है, इसलिए बहुलक = 17।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the fourth proportional to 4, 6 and 10?", "o": ["15", "17", "30", "12"], "a": 0, "e": "4 : 6 = 10 : x → x = 6 × 10/4 = 15.", "qh": "4, 6 और 10 का चौथा समानुपाती क्या है?", "oh": ["15", "17", "30", "12"], "eh": "4 : 6 = 10 : x → x = 6 × 10/4 = 15।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "₹3,600 is divided among Ravi, Arjun and Pooja in the ratio 3 : 4 : 5. What is Pooja's share?", "o": ["₹1,800", "₹2,100", "₹1,500", "₹1,200"], "a": 2, "e": "Total parts = 12; one part = ₹3,600/12 = ₹300; share = 5 × ₹300 = ₹1,500.", "qh": "₹3,600 को रवि, अर्जुन और पूजा में 3 : 4 : 5 के अनुपात में बाँटा गया। पूजा का हिस्सा कितना है?", "oh": ["₹1,800", "₹2,100", "₹1,500", "₹1,200"], "eh": "कुल भाग = 12; एक भाग = ₹3,600/12 = ₹300; हिस्सा = 5 × ₹300 = ₹1,500।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A dishonest grocer uses a weight of 950 g in place of 1 kg and also sells at 10% above cost price. What is his gain percentage?", "o": ["15%", "5%", "16 15/19%", "15 15/19%"], "a": 3, "e": "He gives 950 g but charges for 1000 g at 10% above cost: gain = 1000 × 1.1/950 − 1 = 15 15/19%.", "qh": "एक बेईमान दुकानदार 1 kg की जगह 950 g का बाट इस्तेमाल करता है और साथ में क्रय मूल्य से 10% ज़्यादा दाम पर बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["15%", "5%", "16 15/19%", "15 15/19%"], "eh": "वह 950 g देता है पर 1000 g के पैसे लेता है (क्रय मूल्य से 10% ज़्यादा): लाभ = 1000 × 1.1/950 − 1 = 15 15/19%।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Travelling at 5 km/h, a man reaches his office 15 minutes late. Travelling at 6 km/h, he reaches 10 minutes early. What is the distance to his office?", "o": ["6.25 km", "12.5 km", "13.5 km", "25 km"], "a": 1, "e": "D/5 − D/6 = (15 + 10)/60 h → D = 5 × 6/1 × 25/60 = 12.5 km.", "qh": "5 km/h की रफ़्तार से चलकर एक आदमी दफ़्तर 15 मिनट देर से पहुँचता है। 6 km/h की रफ़्तार से चलकर वह 10 मिनट पहले पहुँचता है। दफ़्तर कितनी दूर है?", "oh": ["6.25 km", "12.5 km", "13.5 km", "25 km"], "eh": "D/5 − D/6 = (15 + 10)/60 h → D = 5 × 6/1 × 25/60 = 12.5 km।", "level": "easy"}, {"s": "Mathematics", "t": "Ages", "q": "A mother is 3 times as old as her daughter. After 10 years, she will be 2 times as old as her daughter. What is the mother's present age?", "o": ["40 years", "20 years", "30 years", "10 years"], "a": 2, "e": "3d + 10 = 2(d + 10) → d = 10; mother = 3 × 10 = 30 years.", "qh": "एक माँ की आयु उसकी बेटी की आयु की 3 गुनी है। 10 साल बाद वह बेटी की आयु की 2 गुनी होगी। माँ की अभी की आयु कितनी है?", "oh": ["40 साल", "20 साल", "30 साल", "10 साल"], "eh": "3d + 10 = 2(d + 10) → d = 10; माँ = 3 × 10 = 30 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "How many numbers from 200 to 600 are divisible by both 4 and 6?", "o": ["34", "33", "68", "36"], "a": 0, "e": "Divisible by both = divisible by LCM 12: ⌊600/12⌋ − ⌊199/12⌋ = 34.", "qh": "200 से 600 तक कितनी संख्याएँ 4 और 6 दोनों से विभाज्य हैं?", "oh": ["34", "33", "68", "36"], "eh": "दोनों से विभाज्य = LCM से विभाज्य 12: ⌊600/12⌋ − ⌊199/12⌋ = 34।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "What is the compound interest on ₹10,000 at 5% per annum for 2 years, compounded annually?", "o": ["₹1,025", "₹11,025", "₹1,000", "₹975"], "a": 0, "e": "Amount = 10000 × (1.05)² = ₹11,025. CI = ₹11,025 − ₹10,000 = ₹1,025.", "qh": "₹10,000 पर 5% वार्षिक दर से 2 साल का चक्रवृद्धि ब्याज (सालाना जुड़ने वाला) कितना होगा?", "oh": ["₹1,025", "₹11,025", "₹1,000", "₹975"], "eh": "मिश्रधन = 10000 × (1.05)² = ₹11,025। चक्रवृद्धि ब्याज = ₹11,025 − ₹10,000 = ₹1,025।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "The edge of a cube is 10 cm. What is its total surface area?", "o": ["120 cm²", "606 cm²", "600 cm²", "400 cm²"], "a": 2, "e": "6a² = 6 × 10² = 600 cm².", "qh": "एक घन की भुजा 10 cm है। उसका कुल पृष्ठीय क्षेत्रफल कितना है?", "oh": ["120 cm²", "606 cm²", "600 cm²", "400 cm²"], "eh": "6a² = 6 × 10² = 600 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A car covers 90 km in 2 hours 30 minutes. What is its speed in metres per second?", "o": ["129.6 m/s", "10 m/s", "20 m/s", "36 m/s"], "a": 1, "e": "Speed = 90/2.5 = 36 km/h = 36 × 5/18 = 10 m/s.", "qh": "एक कार 90 km की दूरी 2 घंटे 30 मिनट में तय करती है। उसकी रफ़्तार मीटर प्रति सेकंड में कितनी है?", "oh": ["129.6 m/s", "10 m/s", "20 m/s", "36 m/s"], "eh": "रफ़्तार = 90/2.5 = 36 km/h = 36 × 5/18 = 10 m/s।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper marks an article 40% above its cost price and allows a discount of 10%. What is his profit percentage?", "o": ["30%", "4%", "26%", "25%"], "a": 2, "e": "SP/CP = 1.4 × 0.9 = 1.26 → profit = 26%.", "qh": "एक दुकानदार वस्तु पर क्रय मूल्य से 40% ज़्यादा दाम लिखता है और 10% छूट देता है। उसका लाभ प्रतिशत क्या है?", "oh": ["30%", "4%", "26%", "25%"], "eh": "विक्रय/क्रय = 1.4 × 0.9 = 1.26 → लाभ = 26%।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A vendor buys 20 bananas for ₹50 and sells 16 bananas for ₹90. What is his profit percentage?", "o": ["250%", "125%", "130%", "80%"], "a": 1, "e": "CP of 1 = 2.5, SP of 1 = 45/8. Profit % = |45/8 − 2.5|/2.5 × 100 = 125%.", "qh": "एक विक्रेता ₹50 में 20 केले खरीदता है और ₹90 में 16 केले बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["250%", "125%", "130%", "80%"], "eh": "1 केले का क्रय मूल्य = 2.5, विक्रय मूल्य = 45/8। प्रतिशत = |45/8 − 2.5|/2.5 × 100 = 125%।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Karan and Deepak can finish a work in 12 days and 24 days respectively. They work together for 4 days and then Karan leaves. In how many days in total will the work be finished?", "o": ["8 days", "12 days", "17 days", "16 days"], "a": 3, "e": "In 4 days: 4 × (1/12 + 1/24) = 0.5 done. Left 0.5 is done by Deepak in 12 days. Total = 16 days.", "qh": "करण और दीपक एक काम क्रमशः 12 दिन और 24 दिन में पूरा कर सकते हैं। दोनों 4 दिन साथ काम करते हैं और फिर करण काम छोड़ देता है। काम कुल कितने दिन में पूरा होगा?", "oh": ["8 दिन", "12 दिन", "17 दिन", "16 दिन"], "eh": "4 दिन में: 4 × (1/12 + 1/24) = 0.5 काम हुआ। बचा 0.5 काम अकेले दीपक से 12 दिन में होता है। कुल = 16 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "A number is increased by 10%, then decreased by 30%, and then increased by 10%. The result is 8470. What was the original number?", "o": ["8470", "11000", "9500", "10000"], "a": 3, "e": "Original × 847/1000 = 8470 → original = 8470 ÷ 847/1000 = 10000.", "qh": "एक संख्या को पहले 10% बढ़ाया, फिर 30% घटाया, और फिर 10% बढ़ाया। नतीजा 8470 आया। मूल संख्या क्या थी?", "oh": ["8470", "11000", "9500", "10000"], "eh": "मूल संख्या × 847/1000 = 8470 → मूल संख्या = 8470 ÷ 847/1000 = 10000।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the area of a triangle whose sides are 7 cm, 24 cm and 25 cm?", "o": ["96 cm²", "84 cm²", "90 cm²", "168 cm²"], "a": 1, "e": "s = (7+24+25)/2 = 28. Area = √[s(s−a)(s−b)(s−c)] = √(28×21×4×3) = 84 cm².", "qh": "उस त्रिभुज का क्षेत्रफल कितना है जिसकी भुजाएँ 7 cm, 24 cm और 25 cm हैं?", "oh": ["96 cm²", "84 cm²", "90 cm²", "168 cm²"], "eh": "s = (7+24+25)/2 = 28. क्षेत्रफल = √[s(s−a)(s−b)(s−c)] = √(28×21×4×3) = 84 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If tan θ = 7/24, what is sin θ? (θ is acute)", "o": ["24/7", "25/7", "7/25", "25/24"], "a": 2, "e": "Opposite = 7, adjacent = 24, hypotenuse = √(7² + 24²) = 25. sin θ = 7/25.", "qh": "अगर tan θ = 7/24 है, तो sin θ क्या है? (θ न्यून कोण है)", "oh": ["24/7", "25/7", "7/25", "25/24"], "eh": "सामने की भुजा = 7, आसन्न भुजा = 24, कर्ण = √(7² + 24²) = 25. sin θ = 7/25।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "If the number 67082* is divisible by 6, what is the digit in place of *?", "o": ["8", "0", "4", "1"], "a": 2, "e": "Rule: even and digit sum divisible by 3. Only * = 4 works: 670824 ÷ 6 = 111804.", "qh": "अगर संख्या 67082* पूरी तरह 6 से विभाज्य है, तो * की जगह कौन-सा अंक है?", "oh": ["8", "0", "4", "1"], "eh": "नियम: सम संख्या और अंकों का योग 3 से विभाज्य। केवल * = 4 सही बैठता है: 670824 ÷ 6 = 111804।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Two table fans are sold for ₹3,600 each. On one there is a gain of 10% and on the other a loss of 10%. What is the overall gain or loss percentage?", "o": ["2% loss", "1% loss", "1% gain", "No profit, no loss"], "a": 1, "e": "When SP is the same and gain% = loss% = 10, there is always a loss of x²/100 = 100/100 = 1%.", "qh": "दो टेबल पंखे ₹3,600 प्रत्येक में बेचे गए। एक पर 10% लाभ और दूसरे पर 10% हानि हुई। कुल मिलाकर कितने प्रतिशत लाभ या हानि हुई?", "oh": ["2% हानि", "1% हानि", "1% लाभ", "न लाभ, न हानि"], "eh": "जब विक्रय मूल्य बराबर हो और लाभ% = हानि% = 10, तो हमेशा x²/100 = 100/100 = 1% हानि होती है।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 3 5/6 + 3 1/6 − 1 1/2", "o": ["6.5", "6", "31/6", "5.5"], "a": 3, "e": "Convert to improper fractions: 23/6, 19/6, 3/2. Working step by step gives 5.5.", "qh": "सरल कीजिए: 3 5/6 + 3 1/6 − 1 1/2", "oh": ["6.5", "6", "31/6", "5.5"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 23/6, 19/6, 3/2। क्रम से हल करने पर 5.5।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "If a = 8, b = 9 and c = 6, what is the value of a² + b² + c² − ab − bc − ca?", "o": ["10", "7", "181", "5"], "a": 1, "e": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[1 + 9 + 4] = 7.", "qh": "अगर a = 8, b = 9 और c = 6 है, तो a² + b² + c² − ab − bc − ca का मान क्या है?", "oh": ["10", "7", "181", "5"], "eh": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[1 + 9 + 4] = 7।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the greatest number that divides 215 and 284, leaving remainders 7 and 11 respectively?", "o": ["17", "15", "26", "13"], "a": 3, "e": "Subtract the remainders: 208, 273. HCF = 13.", "qh": "वह सबसे बड़ी संख्या कौन-सी है जिससे 215 और 284 को भाग देने पर क्रमशः 7 और 11 शेष बचें?", "oh": ["17", "15", "26", "13"], "eh": "शेषफल घटाएँ: 208, 273। HCF = 13।", "level": "easy"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 150 ÷ 15 × 25 + 25 − 9", "o": ["532", "266", "263", "268"], "a": 1, "e": "Follow BODMAS (brackets, then ÷ and × from left to right, then + and −): value = 266.", "qh": "सरल कीजिए: 150 ÷ 15 × 25 + 25 − 9", "oh": ["532", "266", "263", "268"], "eh": "BODMAS के नियम से (पहले कोष्ठक, फिर बाएँ से दाएँ ÷ और ×, फिर + और −): मान = 266।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n6, 10, 18, 34, 66, ?", "o": ["131", "129", "130", "132"], "a": 2, "e": "Rule: ×2 then −2. So ? = 130.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n6, 10, 18, 34, 66, ?", "oh": ["131", "129", "130", "132"], "eh": "नियम: ×2 फिर −2। इसलिए ? = 130।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Amit starts from point P, walks 8 km towards South, then turns left and walks 10 km, then turns right and walks 5 km, then turns left and walks 7 km. In which direction is Amit now with respect to point P?", "o": ["South-East", "North-West", "South-West", "North"], "a": 0, "e": "Net East–West = +17 km, net North–South = -13 km; direction = South-East.", "qh": "अमित बिंदु P से शुरू करके दक्षिण की ओर 8 km चलता है, फिर बाएँ मुड़कर 10 km चलता है, फिर दाएँ मुड़कर 5 km चलता है, फिर बाएँ मुड़कर 7 km चलता है। अब अमित बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पूर्व", "उत्तर-पश्चिम", "दक्षिण-पश्चिम", "उत्तर"], "eh": "कुल पूर्व–पश्चिम = +17 km, कुल उत्तर–दक्षिण = -13 km; दिशा = दक्षिण-पूर्व।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "If 12 March 2022 was a Saturday, what day of the week was 1 October 2023?", "o": ["Monday", "Sunday", "Saturday", "Tuesday"], "a": 1, "e": "Days from 12 March 2022 to 1 October 2023 = 568. 568 = 7 × 81 + 1 → 1 odd day(s) after Saturday = Sunday.", "qh": "अगर 12 मार्च 2022 को शनिवार था, तो 1 अक्टूबर 2023 को कौन-सा दिन था?", "oh": ["सोमवार", "रविवार", "शनिवार", "मंगलवार"], "eh": "12 मार्च 2022 से 1 अक्टूबर 2023 तक दिन = 568। 568 = 7 × 81 + 1 → शनिवार के 1 दिन बाद = रविवार।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["8 – 504", "3 – 24", "5 – 120", "6 – 222"], "a": 3, "e": "In all except 6 – 222: second = (first)³ − first.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["8 – 504", "3 – 24", "5 – 120", "6 – 222"], "eh": "6 – 222 को छोड़कर सभी में: दूसरी = (पहली)³ − पहली।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Mango", "Rose", "Lotus", "Jasmine"], "a": 0, "e": "Mango is a fruit; the others are flowers.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["आम", "गुलाब", "कमल", "चमेली"], "eh": "आम फल है; बाकी फूल हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 50 people, Rohit is 5th from the left and Suresh is 20th from the right. How many people are there between them?", "o": ["25", "26", "24", "23"], "a": 0, "e": "Suresh is 31th from the left. Between = 31 − 5 − 1 = 25.", "qh": "50 लोगों की पंक्ति में रोहित बाएँ से 5वें और सुरेश दाएँ से 20वें स्थान पर है। दोनों के बीच कितने लोग हैं?", "oh": ["25", "26", "24", "23"], "eh": "सुरेश बाएँ से 31वें स्थान पर है। बीच में = 31 − 5 − 1 = 25।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nSome books are clocks.\nSome clocks are not bags.\nAll bags are trees.\nConclusions:\nI. Some bags are clocks.\nII. Some clocks are not books.", "o": ["Both I and II follow", "Neither I nor II follows", "Only conclusion II follows", "Only conclusion I follows"], "a": 1, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकुछ किताबें घड़ियाँ हैं।\nकुछ घड़ियाँ थैले नहीं हैं।\nसभी थैले पेड़ हैं।\nनिष्कर्ष:\nI. कुछ थैले घड़ियाँ हैं।\nII. कुछ घड़ियाँ किताबें नहीं हैं।", "oh": ["I और II दोनों सही हैं", "न I सही है, न II", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "W is the daughter of M. M is the brother of Q. Q is the son of T. How is W related to T?", "o": ["Aunt", "Sister-in-law", "Granddaughter", "Daughter"], "a": 2, "e": "Draw the family tree: W → M: daughter; M → Q: brother; Q → T: son. So W is the granddaughter of T.", "qh": "W, M की बेटी है। M, Q का भाई है। Q, T का बेटा है। W का T से क्या संबंध है?", "oh": ["बुआ/मौसी/चाची", "साली/ननद/भाभी", "पोती/नातिन", "बेटी"], "eh": "परिवार का चार्ट बनाएँ: W → M: बेटी; M → Q: भाई; Q → T: बेटा। इसलिए W, T की पोती/नातिन है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mirror Image", "q": "Which of the following words has all its letters looking the same in a mirror image (mirror placed to the right)? (Capital letters.)", "o": ["OCTAVE", "DOCK", "VOMIT", "AVOID"], "a": 2, "e": "In a side mirror, letters A, H, I, M, O, T, U, V, W, X, Y look the same. Every letter of VOMIT is from this group.", "qh": "नीचे दिए शब्दों में से किस शब्द के सभी अक्षर दर्पण प्रतिबिंब (दर्पण दाईं ओर रखा हो) में वैसे ही दिखेंगे? (बड़े अंग्रेज़ी अक्षर।)", "oh": ["OCTAVE", "DOCK", "VOMIT", "AVOID"], "eh": "बगल के दर्पण में A, H, I, M, O, T, U, V, W, X, Y वैसे ही दिखते हैं। VOMIT के सारे अक्षर इसी समूह के हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: The shop puts up a board: 'Buy one, get one free on all shirts this week.'\nAssumptions:\nI. The offer may attract more buyers.\nII. Shirts will be costlier next week.", "o": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "a": 0, "e": "An offer is given expecting more buyers (I). Nothing implies prices will rise (II).", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: दुकान ने बोर्ड लगाया: 'इस हफ़्ते सभी कमीज़ों पर एक के साथ एक मुफ़्त।'\nधारणाएँ:\nI. यह ऑफ़र ज़्यादा ग्राहक ला सकता है।\nII. अगले हफ़्ते कमीज़ें महँगी हो जाएँगी।", "oh": ["केवल निष्कर्ष I सही है", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "ऑफ़र ज़्यादा ग्राहकों की उम्मीद में दिया जाता है (I)। दाम बढ़ने की कोई बात नहीं (II नहीं)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "L, C, K, D, M, E and Q are sitting in a row, all facing North.\nExactly 1 person sits between D and M.\nL sits second to the right of E.\nL does not sit at either end.\nExactly 4 persons sit between Q and K.\nE is an immediate neighbour of D.\nExactly 2 persons sit between C and M.\nExactly 5 persons sit between C and K.\nWho sits exactly in the middle of the row?", "o": ["K", "L", "C", "M"], "a": 3, "e": "Only one order fits all clues (left to right): K D E M L Q C. Answer: M.", "qh": "L, C, K, D, M, E और Q एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nD और M के बीच ठीक 1 व्यक्ति बैठे हैं।\nL, E के दाईं ओर दूसरे स्थान पर बैठा है।\nL किसी भी छोर पर नहीं बैठा है।\nQ और K के बीच ठीक 4 व्यक्ति बैठे हैं।\nE, D का ठीक पड़ोसी है।\nC और M के बीच ठीक 2 व्यक्ति बैठे हैं।\nC और K के बीच ठीक 5 व्यक्ति बैठे हैं।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["K", "L", "C", "M"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): K D E M L Q C। उत्तर: M।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nSHI : VGM :: RJO : ?", "o": ["SIU", "OKK", "UIS", "UIT"], "a": 2, "e": "Each letter moves +3, -1, +4 in order. RJO → UIS.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nSHI : VGM :: RJO : ?", "oh": ["SIU", "OKK", "UIS", "UIT"], "eh": "हर अक्षर क्रम से +3, -1, +4 खिसकता है। RJO → UIS।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "If the first half of the English alphabet is written in reverse order and then the second half is also written in reverse order, which letter will be 10th from the left?", "o": ["E", "D", "C", "F"], "a": 1, "e": "New order: MLKJIHGFEDCBA ZYXWVUTSRQPON. 10th from left = D.", "qh": "अगर अंग्रेज़ी वर्णमाला के पहले आधे भाग को उलटे क्रम में और फिर दूसरे आधे भाग को भी उलटे क्रम में लिखा जाए, तो बाएँ से 10वाँ अक्षर कौन-सा होगा?", "oh": ["E", "D", "C", "F"], "eh": "नया क्रम: MLKJIHGFEDCBA ZYXWVUTSRQPON। बाएँ से 10वाँ = D।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n2, 3, 5, 9, 17, ?", "o": ["34", "35", "33", "38"], "a": 2, "e": "Rule: ×2 then −1. So ? = 33.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n2, 3, 5, 9, 17, ?", "oh": ["34", "35", "33", "38"], "eh": "नियम: ×2 फिर −1। इसलिए ? = 33।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n14 : 2744 :: 3 : ?", "o": ["30", "33", "27", "28"], "a": 2, "e": "Rule: x → x³. 14 → 2744, so 3 → 27.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n14 : 2744 :: 3 : ?", "oh": ["30", "33", "27", "28"], "eh": "नियम: x → x³। 14 → 2744, इसलिए 3 → 27।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nA81Z, D100W, G121T, J144Q, ?", "o": ["M168N", "L169M", "M169O", "M169N"], "a": 3, "e": "First letter +3; number: consecutive squares; last letter -3. So ? = M169N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nA81Z, D100W, G121T, J144Q, ?", "oh": ["M168N", "L169M", "M169O", "M169N"], "eh": "पहला अक्षर +3; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -3। इसलिए ? = M169N।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'KITTEN' is written as 'PGVVKM'. How will 'SCHOOL' be written in that language?", "o": ["UEJQQN", "NQQJET", "NQRJEU", "NQQJEU"], "a": 3, "e": "Rule: the word is reversed and each letter moves +2. Applying it to SCHOOL gives NQQJEU.", "qh": "एक कोड भाषा में 'KITTEN' को 'PGVVKM' लिखा जाता है। उसी भाषा में 'SCHOOL' को कैसे लिखा जाएगा?", "oh": ["UEJQQN", "NQQJET", "NQRJEU", "NQQJEU"], "eh": "नियम: शब्द उलटा करके हर अक्षर +2 खिसकता है। SCHOOL पर लगाने से NQQJEU मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "R, D, Q, F, U and W are sitting around a circular table, all facing the centre.\nD is an immediate neighbour of W.\nW sits immediately to the left of Q.\nU sits immediately to the left of D.\nU is an immediate neighbour of F.\nWho sits to the immediate right of W?", "o": ["R", "Q", "U", "F"], "a": 1, "e": "Only one arrangement fits. Going to the right (anticlockwise) from W: W → Q → R → F → U → D. Answer: Q.", "qh": "R, D, Q, F, U और W एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nD, W का ठीक पड़ोसी है।\nW, Q के ठीक बाईं ओर बैठा है।\nU, D के ठीक बाईं ओर बैठा है।\nU, F का ठीक पड़ोसी है।\nW के ठीक दाईं ओर कौन बैठा है?", "oh": ["R", "Q", "U", "F"], "eh": "केवल एक व्यवस्था बैठती है। W से दाईं ओर (घड़ी की उलटी दिशा में) चलें: W → Q → R → F → U → D। उत्तर: Q।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nKilogram : Mass :: Ampere : ?", "o": ["Voltage", "Power", "Electric current", "Resistance"], "a": 2, "e": "Relation: 'SI unit of'. Kilogram – Mass, so Ampere – Electric current.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nकिलोग्राम : द्रव्यमान :: ऐम्पियर : ?", "oh": ["वोल्टेज", "शक्ति", "विद्युत धारा", "प्रतिरोध"], "eh": "संबंध: 'की SI इकाई'। किलोग्राम – द्रव्यमान, इसलिए ऐम्पियर – विद्युत धारा।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n692   725   783   718   682\nFor the number whose digits add up to the smallest total, what is the product of its first and last digits?", "o": ["33", "38", "35", "34"], "a": 2, "e": "Digit sums: 17, 14, 18, 16, 16. Smallest belongs to 725: 7 × 5 = 35.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n692   725   783   718   682\nजिस संख्या के अंकों का योग सबसे कम है, उसके पहले और आखिरी अंक का गुणनफल क्या है?", "oh": ["33", "38", "35", "34"], "eh": "अंकों के योग: 17, 14, 18, 16, 16। सबसे कम 725 का है: 7 × 5 = 35।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "Pointing to a photograph, a man said, \"This person is the only brother of my mother's only daughter.\" How is the person in the photograph related to the man?", "o": ["Father", "Son", "Brother", "Himself"], "a": 3, "e": "Simplify from the end: 'the only brother of my mother's only daughter' is the man himself.", "qh": "एक तस्वीर की ओर इशारा करते हुए एक आदमी ने कहा, \"यह व्यक्ति मेरी माँ की इकलौती बेटी का इकलौता भाई है।\" तस्वीर वाला व्यक्ति उस आदमी का क्या लगता है?", "oh": ["पिता", "बेटा", "भाई", "वह खुद"], "eh": "आखिर से सरल करें: 'मेरी माँ की इकलौती बेटी का इकलौता भाई' = वह खुद।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n4 9 4 1 5 9 3 7 6 2 8 5 1 4 7 7 9 9 7 1 3 6 4 9 9\nHow many even digits are there, each of which is immediately preceded by an odd digit AND immediately followed by a digit greater than 5?", "o": ["3", "1", "2", "4"], "a": 1, "e": "Matching groups: 1 4 7 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n4 9 4 1 5 9 3 7 6 2 8 5 1 4 7 7 9 9 7 1 3 6 4 9 9\nऐसे कितने सम अंक हैं, जिनके ठीक पहले विषम अंक हो और ठीक बाद 5 से बड़ा अंक हो?", "oh": ["3", "1", "2", "4"], "eh": "शर्त पूरी करने वाले समूह: 1 4 7 → 1।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nCF, GJ, KN, OR, ?", "o": ["SV", "SU", "SX", "SW"], "a": 0, "e": "Letter positions move by +4, +4 (for 1st, 2nd letters). So ? = SV.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nCF, GJ, KN, OR, ?", "oh": ["SV", "SU", "SX", "SW"], "eh": "अक्षरों की स्थिति +4, +4 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = SV।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "6 boxes R, X, U, Q, P and S are kept one above the other (not necessarily in this order).\nExactly 2 boxes are placed between boxes Q and R.\nBox P is 1st from the bottom.\nBox U is 3rd from the bottom.\nBox Q is placed somewhere above box R.\nExactly 4 boxes are placed between boxes S and P.\nHow many boxes are placed above box Q?", "o": ["0", "3", "2", "1"], "a": 3, "e": "Only one order fits (bottom to top): P R U X Q S. Answer: 1.", "qh": "6 डिब्बे R, X, U, Q, P और S एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बे Q और R के बीच ठीक 2 डिब्बे रखे हैं।\nडिब्बा P नीचे से 1वें स्थान पर है।\nडिब्बा U नीचे से 3वें स्थान पर है।\nडिब्बा Q, डिब्बे R से कहीं ऊपर रखा है।\nडिब्बे S और P के बीच ठीक 4 डिब्बे रखे हैं।\nडिब्बे Q के ऊपर कितने डिब्बे रखे हैं?", "oh": ["0", "3", "2", "1"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): P R U X Q S। उत्तर: 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "One evening, before sunset, Rahul was standing facing a pole. The shadow of the pole fell exactly to his right. Which direction was Rahul facing?", "o": ["East", "South", "West", "North"], "a": 3, "e": "In the evening the Sun is in the West, so shadows fall towards the East. Shadow to his right → he faces North.", "qh": "एक दिन शाम को सूरज डूबने से पहले राहुल एक खंभे की ओर मुँह करके खड़ा था। खंभे की परछाईं ठीक उसके दाईं ओर पड़ी। राहुल किस दिशा की ओर मुँह करके खड़ा था?", "oh": ["पूर्व", "दक्षिण", "पश्चिम", "उत्तर"], "eh": "शाम को सूरज पश्चिम में होता है, इसलिए परछाईं पूर्व की ओर पड़ती है। परछाईं उसके दाईं ओर → वह उत्तर की ओर देख रहा है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n9 − 14 × 4 + 18 ÷ 2 = 131", "o": ["+ and −", "× and ÷", "− and ×", "− and ÷"], "a": 2, "e": "Interchanging − and ×: 9 × 14 − 4 + 18 ÷ 2 = 131. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n9 − 14 × 4 + 18 ÷ 2 = 131", "oh": ["+ और −", "× और ÷", "− और ×", "− और ÷"], "eh": "− और × बदलने पर: 9 × 14 − 4 + 18 ÷ 2 = 131। ✔", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'green water blue' is written as 'bo mo dy',\n'milk green long' is written as 'ni pu dy',\n'water clean milk' is written as 'bo su ni',\nWhat is the code for 'green'?", "o": ["bo", "mo", "ni", "dy"], "a": 3, "e": "Compare the sentences: common words and common codes match. This gives 'green' = 'dy'.", "qh": "एक कोड भाषा में:\n'green water blue' को 'bo mo dy' लिखा जाता है,\n'milk green long' को 'ni pu dy' लिखा जाता है,\n'water clean milk' को 'bo su ni' लिखा जाता है,\n'green' का कोड क्या है?", "oh": ["bo", "mo", "ni", "dy"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'green' = 'dy' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["NSUY", "KOQU", "LPRV", "GKMQ"], "a": 0, "e": "In KOQU, LPRV, GKMQ the gaps are +4, +2, +4; in NSUY they are +5, +2, +4.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["NSUY", "KOQU", "LPRV", "GKMQ"], "eh": "KOQU, LPRV, GKMQ में अंतर +4, +2, +4 है; NSUY में +5, +2, +4 है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nD 9 © H E Q 4 4 A 3 L P @ 7 S + * € 3 O % ©\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["4", "1", "2", "3"], "a": 2, "e": "Matching places: @7S, €3O → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nD 9 © H E Q 4 4 A 3 L P @ 7 S + * € 3 O % ©\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["4", "1", "2", "3"], "eh": "शर्त पूरी करने वाले स्थान: @7S, €3O → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '×', '×' means '÷', '÷' means '+', then what is the value of the following expression?\n24 − 18 ÷ 18 ÷ 29 ÷ 30 = ?", "o": ["1018", "511", "519", "509"], "a": 3, "e": "Replace the signs: 24 × 18 + 18 + 29 + 30 = 509 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '×', '×' का मतलब '÷', '÷' का मतलब '+' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n24 − 18 ÷ 18 ÷ 29 ÷ 30 = ?", "oh": ["1018", "511", "519", "509"], "eh": "चिह्न बदलें: 24 × 18 + 18 + 29 + 30 = 509 (BODMAS से)।", "level": "tough"}]});
